// =============================================================================
// File        : tb_systolic_top.v
// Owner       : Member 5
// Description : System-level self-checking testbench for systolic_top.
//
//   For every test case stored in tests/vectors/vectors.hex (generated by the
//   Python golden model, model/golden_model.py) the testbench
//     1. writes A and B through the matrix data interface (wr_* port),
//     2. pulses start and waits for done,
//     3. reads all N*N results through the rd_addr / rd_data port,
//     4. compares them with the golden-model results.
//
//   It also reports the observed start->done cycle count per run.
// Run  : see sim/Makefile  ->  make top
// =============================================================================
`timescale 1ns / 1ps

`ifndef VEC_DIR
 `define VEC_DIR "../tests/vectors/"
`endif

module tb_systolic_top;

    localparam N         = 4;
    localparam DATA_W    = 8;
    localparam ACC_W     = 32;
    localparam AW        = 4;            // clog2(N*N)
    localparam NN        = N*N;
    localparam MAX_TESTS = 64;
    localparam WORDS     = MAX_TESTS*3*NN;

    reg                      clk, rst_n, start;
    reg                      wr_en, wr_sel;
    reg  [AW-1:0]            wr_addr, rd_addr;
    reg  [DATA_W-1:0]        wr_data;
    wire                     busy, done;
    wire signed [ACC_W-1:0]  rd_data;

    reg  [31:0] vec [0:WORDS-1];
    reg  [31:0] cnt [0:0];

    integer t, e, num_tests, base;
    integer errors = 0, test_err;
    integer cycles;

    systolic_top #(.N(N), .DATA_W(DATA_W), .ACC_W(ACC_W), .AW(AW)) dut (
        .clk(clk), .rst_n(rst_n),
        .start(start), .busy(busy), .done(done),
        .wr_en(wr_en), .wr_sel(wr_sel), .wr_addr(wr_addr), .wr_data(wr_data),
        .rd_addr(rd_addr), .rd_data(rd_data)
    );

    initial clk = 1'b0;
    always #5 clk = ~clk;      // 100 MHz

    // ---------------- interface tasks ----------------
    task write_elem;
        input             sel;
        input [AW-1:0]    addr;
        input [DATA_W-1:0] data;
        begin
            wr_en = 1; wr_sel = sel; wr_addr = addr; wr_data = data;
            @(posedge clk); #1;
            wr_en = 0;
        end
    endtask

    task run_matmul;
        begin
            start = 1; @(posedge clk); #1; start = 0;
            cycles = 1;
            while (!done) begin
                @(posedge clk); #1;
                cycles = cycles + 1;
            end
        end
    endtask

    // ---------------- main sequence ----------------
    initial begin
        $dumpfile("tb_systolic_top.vcd");
        $dumpvars(0, tb_systolic_top);

        $readmemh({`VEC_DIR, "vectors_count.hex"}, cnt);
        num_tests = cnt[0];
        if (num_tests > MAX_TESTS) num_tests = MAX_TESTS;
        $readmemh({`VEC_DIR, "vectors.hex"}, vec, 0, num_tests*3*NN - 1);

        $display("==================================================");
        $display(" tb_systolic_top : %0d golden-model test cases", num_tests);
        $display("==================================================");

        rst_n = 0; start = 0; wr_en = 0; wr_sel = 0;
        wr_addr = 0; wr_data = 0; rd_addr = 0;
        #22 rst_n = 1;
        @(posedge clk); #1;

        for (t = 0; t < num_tests; t = t + 1) begin
            base     = t*3*NN;
            test_err = 0;

            // 1. load operands
            for (e = 0; e < NN; e = e + 1) write_elem(1'b0, e, vec[base + e][DATA_W-1:0]);
            for (e = 0; e < NN; e = e + 1) write_elem(1'b1, e, vec[base + NN + e][DATA_W-1:0]);

            // 2. compute
            run_matmul;

            // 3. read back + 4. compare
            for (e = 0; e < NN; e = e + 1) begin
                rd_addr = e; #1;
                if (rd_data !== $signed(vec[base + 2*NN + e])) begin
                    test_err = test_err + 1;
                    $display("    mismatch C[%0d][%0d]: got %0d expected %0d",
                             e / N, e % N, rd_data, $signed(vec[base + 2*NN + e]));
                end
            end

            if (test_err == 0)
                $display("  [PASS] test %0d : 16/16 elements correct, start->done = %0d cycles",
                         t, cycles);
            else
                $display("  [FAIL] test %0d : %0d mismatches", t, test_err);
            errors = errors + test_err;
            @(posedge clk); #1;
        end

        $display("--------------------------------------------------");
        if (errors == 0) $display(" RESULT: ALL %0d SYSTEM TESTS PASSED", num_tests);
        else             $display(" RESULT: SYSTEM TESTS FAILED (%0d element errors)", errors);
        $display("==================================================");
        #20 $finish;
    end

    // safety timeout
    initial begin
        #200000;
        $display(" TIMEOUT");
        $finish;
    end

endmodule
